def F(x):
    t0 = np.clip(-1000.0 * x, -500.0, 500.0)
    t1 = np.clip(1000.0 * (x - 1.0), -500.0, 500.0)
    return np.floor(np.clip(255.0 * np.exp(-np.exp(t0)) * (np.maximum(np.abs(x), 1e-15) ** np.exp(-np.exp(t1))), 0, 255)).astype(np.uint8)

def render():
    m = np.arange(1, W + 1, dtype=np.float64)
    n = np.arange(1, H + 1, dtype=np.float64)
    x_grid, y_grid = (m[None, :] - M0) / S, (N0 - n[:, None]) / S
    out = np.zeros((H, W, 3), dtype=np.uint8)

    u_arr = np.array([t[0] for t in TRIG_TERMS], dtype=np.float64)
    v_arr = np.array([t[1] for t in TRIG_TERMS], dtype=np.float64)
    c0_arr = np.array([t[2] for t in TRIG_TERMS], dtype=np.float64)
    c1_arr = np.array([t[3] for t in TRIG_TERMS], dtype=np.float64)
    c2_arr = np.array([t[4] for t in TRIG_TERMS], dtype=np.float64)

    cos_y = np.cos(np.pi * (n[:, None] - 0.5) * u_arr[None, :] / H) if len(TRIG_TERMS) else None
    cos_x = np.cos(np.pi * v_arr[:, None] * (m[None, :] - 0.5) / W) if len(TRIG_TERMS) else None

    for s in range(3):
        prod = np.ones((H, W), dtype=np.float64)
        for (x0, y0, th, a, b, k, c0, c1, c2) in PRIMITIVES:
            ct, st = np.cos(th), np.sin(th)
            u = ((x_grid - x0) * ct + (y_grid - y0) * st) / a
            v = (-(x_grid - x0) * st + (y_grid - y0) * ct) / b
            A_p = np.exp(-np.exp(np.clip(k * (u**2 + v**2 - 1.0), -40.0, 40.0)))
            w_s = np.clip(c0 + c1 * s + c2 * (s ** 2), 0.0, 1.0)
            prod *= (1.0 - w_s * A_p)
        C_s = (cos_y * (c0_arr + c1_arr * s + c2_arr * (s**2))[None, :]) @ cos_x if len(TRIG_TERMS) else 0.0
        out[:, :, s] = F((1.0 - prod) + C_s)

    Image.fromarray(out).save("reconstructed_from_equation.png")
    print("Saved reconstructed_from_equation.png")

if __name__ == "__main__":
    render()
